const $=s=>document.querySelector(s);
let session=null,mode='manage',linkToken='',settings=null;
const fragment=new URLSearchParams(location.hash.slice(1));
for(const action of ['verify','reset','invite','forgot'])if(fragment.has(action)){mode=action;linkToken=fragment.get(action)||'';break;}
if(location.hash)history.replaceState(null,'',location.pathname);
function message(text,error=false){$('#account-status').textContent=error?'':text;$('#page-error').textContent=error?text:'';$('#page-error').hidden=!error;}
async function request(endpoint,{method='GET',body}={}){const headers={};if(body)headers['Content-Type']='application/json';if(session?.csrfToken&&method!=='GET')headers['X-CSRF-Token']=session.csrfToken;const res=await fetch(endpoint,{method,headers,body:body?JSON.stringify(body):undefined,credentials:'same-origin',cache:'no-store',redirect:'error'});const data=await res.json().catch(()=>{throw new Error('Account settings are available on your connected server’s website.');});if(!res.ok)throw new Error(data.error||'This request could not be completed.');return data;}
function form(title,fields,button,submit){$('#page-title').textContent=title;const panel=$('#action-panel');panel.replaceChildren();const element=document.createElement('form');element.className='account-fields';for(const field of fields){const label=document.createElement('label');label.textContent=field.label;label.htmlFor=field.name;const input=document.createElement('input');input.id=field.name;input.name=field.name;input.type=field.type||'text';input.autocomplete=field.auto||'off';input.required=true;if(field.type==='password'){input.minLength=12;input.maxLength=128;}if(field.type==='email')input.maxLength=254;element.append(label,input);}const send=document.createElement('button');send.type='submit';send.className='primary-button wide';send.textContent=button;element.append(send);element.addEventListener('submit',async event=>{event.preventDefault();send.disabled=true;$('#page-error').hidden=true;try{await submit(Object.fromEntries(new FormData(element)));}catch(error){message(error.message,true);}finally{send.disabled=false;}});panel.append(element);}
async function refresh(){session=await request('/api/auth/session');render();}
function render(){
 const panel=$('#action-panel');
 if(mode==='verify'){message('Confirm the email address used for this ClipNest account.');form('Verify your email',[],'Verify email',async()=>{await request('/api/auth/verify',{method:'POST',body:{token:linkToken}});mode='manage';linkToken='';message('Email verified. You can prepare a download.');await refresh();});return;}
 if(mode==='reset'){message('Choose a new password. This signs out your previous sessions.');form('Reset your password',[{name:'password',label:'New password',type:'password',auto:'new-password'},{name:'confirm',label:'Repeat new password',type:'password',auto:'new-password'}],'Reset password',async data=>{if(data.password!==data.confirm)throw new Error('Passwords do not match.');await request('/api/auth/reset',{method:'POST',body:{token:linkToken,password:data.password}});mode='login';linkToken='';message('Password updated. Sign in to continue.');session=null;render();});return;}
 if(mode==='forgot'){message('We will send a link if this account can receive email.');form('Recover your account',[{name:'email',label:'Email address',type:'email',auto:'username'}],'Send recovery email',async data=>{const response=await request('/api/auth/forgot',{method:'POST',body:data});message(response.message);});return;}
 if(mode==='invite'){message('Use the email address that received this invitation.');form('Join the private beta',[{name:'email',label:'Invited email address',type:'email',auto:'username'},{name:'password',label:'Choose a password',type:'password',auto:'new-password'}],'Create account',async data=>{session=await request('/api/auth/register',{method:'POST',body:{...data,invitationToken:linkToken}});mode='manage';linkToken='';message('Account created. Check your email if verification is requested.');render();});return;}
 if(!session?.user){form('Sign in',[{name:'email',label:'Email address',type:'email',auto:'username'},{name:'password',label:'Password',type:'password',auto:'current-password'}],'Sign in',async data=>{session=await request('/api/auth/login',{method:'POST',body:data});mode='manage';render();});const recovery=document.createElement('a');recovery.href='/account.html#forgot';recovery.textContent='Forgot password?';panel.append(recovery);return;}
 $('#page-title').textContent='Your account';message(session.user.email);panel.innerHTML='<div class="account-actions"><a class="primary-button" href="/">Prepare a download</a><button id="export-account" class="subtle-button" type="button">Download my account data</button><button id="logout-account" class="subtle-button" type="button">Sign out</button></div><div id="verify-actions" hidden><p>Verify your email before preparing downloads.</p><button id="send-verification" class="text-button" type="button">Resend verification email</button></div><details class="account-delete"><summary>Delete my account</summary><p>This signs out all sessions, cancels active requests and schedules deletion of prepared files. History follows the retention policy.</p><form id="delete-account-form" class="account-fields"><label for="delete-password">Current password</label><input id="delete-password" name="password" type="password" autocomplete="current-password" required><label class="deletion-confirm"><input id="delete-confirm" type="checkbox" required>I understand that my account access will be removed.</label><button class="primary-button" type="submit">Delete my account</button></form></details>';
 $('#verify-actions').hidden=!settings?.requireEmailVerification||session.user.verified;
 $('#send-verification').addEventListener('click',async()=>{try{await request('/api/auth/resend',{method:'POST'});message('If verification is needed, an email will be sent.');}catch(e){message(e.message,true);}});
 $('#logout-account').addEventListener('click',async()=>{try{await request('/api/auth/logout',{method:'POST'});session=null;mode='login';message('Signed out.');render();}catch(e){message(e.message,true);}});
 $('#export-account').addEventListener('click',async()=>{try{const data=await request('/api/account/export'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='clipnest-account.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);message('Your account export is ready.');}catch(e){message(e.message,true);}});
 $('#delete-account-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button');button.disabled=true;try{await request('/api/account',{method:'DELETE',body:{password:$('#delete-password').value}});session=null;mode='login';message('Your account has been closed. Prepared-file deletion is scheduled.');render();}catch(e){message(e.message,true);}finally{button.disabled=false;}});
 if(session.user.operator){const ops=document.createElement('a');ops.href='/operator.html';ops.textContent='Operator controls';panel.prepend(ops);}
}
(async()=>{try{settings=await request('/api/config');if(settings.authMode!=='session')throw new Error('Account settings require an account-enabled ClipNest server.');await refresh();}catch(e){message(e.message,true);}})();
